/bin/zsh -lc "cat > package.json <<'EOF'
{\"name\":\"living-garden\",\"version\":\"1.0.0\",\"type\":\"module\",\"scripts\":{\"dev\":\"node server.js\",\"start\":\"node server.js\",\"check\":\"node --check app.js && node --check simulation.js && node --check server.js\"}}
EOF
cat > server.js <<'EOF'
import http from 'node:http';
import {readFile} from 'node:fs/promises';
import path from 'node:path';
const root=process.cwd();
http.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');const file=path.resolve(root,'.'+(url.pathname==='/'?'/index.html':url.pathname));if("'!file.startsWith(root+path.sep))throw Error();const data=await readFile(file);res.setHeader('"'Content-Type',({'html':'text/html','js':'text/javascript','css':'text/css','svg':'image/svg+xml'})[file.split('.').pop()]||'application/octet-stream');res.end(data)}catch{res.writeHead(404);res.end('Not found')}}).listen(9194,'0.0.0.0',()=>console.log('Garden at http://localhost:9194'));
EOF
cat > index.html <<'EOF'
<"'!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>GPT-6</title><link rel="stylesheet" href="style.css"></head><body>
<header><a class="brand" href="./"><span class="brand-icon">❋</span><h1>GPT-6</h1><span class="brand-divider"></span><span class="brand-sub">a little world, a living balance</span></a><button class="guide-button" id="guide">ⓘ <span>Field guide</span></button></header>
<main><section class="workspace"><div class="world-heading"><div><div class="eyebrow">THE LIVING GARDEN</div><h2>Small world. Big possibilities.</h2><p>A few simple rules. A whole ecosystem of surprises.</p></div><span class="live-badge"><i></i><span id="status">Garden is resting</span></span></div>
<div class="world-wrap"><canvas id="world" aria-label="Interactive garden. Drag to rotate and click a blob to inspect."></canvas><div class="world-top"><span class="world-label"><i></i><span id="preset-label">Balanced garden</span></span><span class="seed-label">SEED <b id="seed-label">1042</b></span></div><div class="world-bottom"><span>↔ &nbsp; Drag to rotate <span class="hint-divider">·</span> Click a blob to say hello</span><button id="view-reset" title="Reset camera">⤾</button></div><div id="inspector" class="inspector" hidden></div></div>
<div class="playbar"><div class="play-buttons"><button class="primary" id="play"><span>▶</span> Play garden</button><button class="icon-button" id="step" title="Advance one second">▸│</button><span class="separator"></span><button class="text-button" id="reset">↻ <span>Reset</span></button></div><div class="speed-control"><span>Speed</span><div class="segmented" id="speeds"><button data-speed="0.5">½×</button><button class="active" data-speed="1">1×</button><button data-speed="2">2×</button><button data-speed="5">5×</button></div></div><div class="time"><span class="clock-icon">◷</span><b id="time">00:00</b></div></div>
<div class="stats"><div class="stat fruit"><span class="stat-icon">♧</span><div><span>Available fruit</span><strong id="fruit-count">0</strong></div><span class="stat-note">the little fuel</span></div><div class="stat blue"><span class="mini-blob"></span><div><span>Blue blobs</span><strong id="blue-count">0</strong></div><span class="stat-note">the gatherers</span></div><div class="stat red"><span class="mini-blob"></span><div><span>Red blobs</span><strong id="red-count">0</strong></div><span class="stat-note">the chasers</span></div></div>
